// Workaround del n8n Proxy bug: clonar profundamente para des-proxiear
const rawIn = $input.first().json;
const raw = JSON.parse(JSON.stringify(rawIn || {}));

let rawBody = {};
if (raw && typeof raw.body === 'object' && Object.keys(raw.body).length) rawBody = raw.body;
else if (raw && typeof raw.query === 'object' && Object.keys(raw.query).length) rawBody = raw.query;
else if (typeof raw === 'object') rawBody = raw;

function tk(obj){ const o={}; for(const k in obj) o[String(k).trim()] = obj[k]; return o; }
const customData = (rawBody.customData && typeof rawBody.customData === 'object') ? tk(rawBody.customData) : {};
const body = tk(rawBody);

function pick(key){
  if (body[key] !== undefined && body[key] !== null && body[key] !== '') return body[key];
  if (customData[key] !== undefined && customData[key] !== null && customData[key] !== '') return customData[key];
  return null;
}

const MONTHS = {January:0,February:1,March:2,April:3,May:4,June:5,July:6,August:7,September:8,October:9,November:10,December:11};
function parseGHLDate(s) {
  if (!s || typeof s !== 'string') return null;
  const m = s.match(/\w+,\s+(\w+)\s+(\d+),\s+(\d+)\s+(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return null;
  let [, mon, day, year, h, mi, ap] = m;
  let H = parseInt(h, 10) % 12;
  if (/PM/i.test(ap)) H += 12;
  const mon_n = MONTHS[mon]; if (mon_n === undefined) return null;
  const pad = n => String(n).padStart(2, '0');
  return `${year}-${pad(mon_n+1)}-${pad(day)}T${pad(H)}:${pad(mi)}:00-05:00`;
}
function normalizePhone(p) {
  if (!p) return null;
  const d = String(p).replace(/\D/g, '');
  if (!d) return null;
  if (d.length === 10) return '52' + d;
  if (d.length === 12 && d.startsWith('52')) return d;
  if (d.length === 13 && d.startsWith('521')) return '52' + d.slice(3);
  return d;
}
function shortCode() {
  const ts = Date.now().toString(36).toUpperCase().slice(-5);
  const rnd = Math.random().toString(36).toUpperCase().slice(2, 5);
  return `EX-${ts}${rnd}`;
}

const appointment_id = pick('appointment_id') || (body.calendar && body.calendar.appointmentId) || null;
const contact_id = pick('contact_id');
const email = pick('email');
const phone = pick('phone');
const first_name = pick('first_name');
const last_name = pick('last_name');
const start_time = pick('start_time');
const end_time = pick('end_time');

const startISO = parseGHLDate(start_time);
const endISO = parseGHLDate(end_time);
const startDate = startISO ? startISO.slice(0,10) : null;
const startTimeOnly = startISO ? startISO.slice(11,19) : null;
const durationMin = (startISO && endISO) ? Math.round((new Date(endISO)-new Date(startISO))/60000) : null;
const nombre = [first_name, last_name].filter(Boolean).join(' ').trim() || null;

const BODY_KEYS = {
  servicio_elegido: ['exentia_servicio_elegido'],
  lead_ref: ['exentia_lead_ref'],
  fbclid: ['exentia_fbclid'],
  gclid: ['exentia_gclid'],
  utm_source: ['exentia_utm_source_last','exentia_utm_source_first'],
  utm_medium: ['exentia_utm_medium_last','exentia_utm_medium_first'],
  utm_campaign: ['exentia_utm_campaign_last','exentia_utm_campaign_first'],
  zona: ['exentia_zona'],
  preferencia_sexo: ['exentia_preferencia_sexo'],
  valor_ticket_mxn: ['exentia_valor_ticket_mxn']
};
const extracted = {};
for (const [key, sources] of Object.entries(BODY_KEYS)) {
  for (const s of sources) { if (body[s]) { extracted[key] = body[s]; break; } }
  if (!extracted[key]) extracted[key] = null;
}

let servicios = [];
if (extracted.servicio_elegido) {
  servicios = String(extracted.servicio_elegido)
    .split(',').map(s => s.trim()).filter(Boolean).map(s => ({ slug: s }));
}

const atribucion = {};
if (extracted.fbclid) atribucion.fbclid = extracted.fbclid;
if (extracted.gclid) atribucion.gclid = extracted.gclid;
if (extracted.utm_source) atribucion.utm_source = extracted.utm_source;
if (extracted.utm_medium) atribucion.utm_medium = extracted.utm_medium;
if (extracted.utm_campaign) atribucion.utm_campaign = extracted.utm_campaign;

return [{
  json: {
    ghl_appointment_id: appointment_id,
    ghl_contact_id: contact_id,
    cliente_email: email,
    cliente_telefono: normalizePhone(phone),
    cliente_nombre: nombre,
    fecha_agendada: startDate,
    hora_agendada: startTimeOnly,
    duracion_total_min: durationMin,
    booking_code: shortCode(),
    servicios: servicios,
    lead_ref: extracted.lead_ref,
    zona_colonia: extracted.zona,
    preferencia_sexo: (extracted.preferencia_sexo || 'I').toUpperCase().charAt(0),
    valor_ticket_mxn: extracted.valor_ticket_mxn ? parseFloat(String(extracted.valor_ticket_mxn).replace(/[^0-9.]/g,'')) : null,
    atribucion: Object.keys(atribucion).length > 0 ? atribucion : null,
    ghl_enriched: Object.keys(body).some(k => String(k).startsWith('exentia_'))
  }
}];

